mapper.select:
        select
        *
        from
        wms_material_unfreeze
        where
        bool_delete_enum = 0
        
            and freeze_type in
            
                #{item}
            
        
        
            and freeze_detail_id = #{freezeDetailId}
        
        
            and material_is_whole = #{materialIsWhole}
        
        
            and source_project_id is not null
        
        
            and source_project_id = #{projectId}
        
        
            and source_project_id is null
        

        
            and basic_class & #{ basicClass} > 0
        
        
            and theory_thickness = #{theoryThickness}
        
        
            and thickness = #{thickness}
        
        
            and width = #{width}
        
        
            and length = #{length}
        
        
        -- 长度范围只针对钢卷
            and quantity >= #{minLength}
        
        
            and quantity <= #{maxLength}
        
        
            and specification like  CONCAT('%', #{specification},'%')
        
        
            and heat_no_and_batch_no like  CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            and classify_id in
            
                #{item}
            
        



        
            and workshop_id = #{workshopId}
        
        
            and warehouse_id = #{warehouseId}
        
        
            and color like  CONCAT('%', #{color},'%')
        
        
            and brand like  CONCAT('%', #{brand},'%')
